// Insert models into detailedCatalog
let globalIndex = 21;
for (const [catKey, items] of Object.entries(sampleModels)) {
  const catTemplate = categoryTemplates.find(c => c.slug === catKey);
  const catName = catTemplate ? catTemplate.catName : catKey;
  const defaultImg = catTemplate ? catTemplate.img : "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80";

  for (const item of items) {
    const pId = `nx-${catKey.substring(0, 2)}-${String(globalIndex).padStart(2, '0')}`;
    globalIndex++;

    detailedCatalog.push({
      id: pId,
      name: item.name,
      slug: item.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
      brand: item.brand,
      model: item.model,
      category: catKey,
      categoryName: catName,
      price: item.price,
      discountPrice: item.discount,
      primaryImage: item.img || defaultImg,
      galleryImages: [item.img || defaultImg],
      description: item.description || `${item.brand} ${item.model} — eng yuqori sifat va innovatsion texnologiyalarga ega flagman model. NEXORA kafolati bilan rasmiy taqdim etiladi.`,
      specs: item.specs || {},
      stock: Math.floor(Math.random() * 20) + 3,
      rating: parseFloat((4.7 + Math.random() * 0.3).toFixed(2)),
      reviewsCount: Math.floor(Math.random() * 45) + 6,
      warrantyMonths: catKey === 'cpus' || catKey === 'gpus' || catKey === 'desktops' ? 36 : 24,
      isInStock: true,
      isFeatured: detailedCatalog.length % 7 === 0,
      isBestseller: detailedCatalog.length % 5 === 0,
      isNew: detailedCatalog.length % 6 === 0,
      createdAt: new Date(Date.now() - Math.floor(Math.random() * 10000000000)).toISOString()
    });
  }
}

console.log(`Generated ${detailedCatalog.length} unique products!`);

const outputTs = `// AUTOGENERATED COMPREHENSIVE PRODUCT CATALOG FOR NEXORA
// Exactly ${detailedCatalog.length} distinct high-tech products across 15 categories with authentic specs, UZS pricing, and image mapping.
import { Product } from "@/types";

export const INITIAL_PRODUCTS: Product[] = ${JSON.stringify(detailedCatalog, null, 2)};
`;

fs.writeFileSync(path.join(__dirname, '../src/data/products.ts'), outputTs, 'utf-8');
console.log('Saved to src/data/products.ts successfully.');
